 "content": "def transform(grid):
    """Mark the enclosed/background side of the 5-pixel drawing with 8,
    and mark the one-pixel terminal tail with 7."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Flood-fill 0s connected to the outside of the grid (4-neighbor).
    from collections import deque
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in outside:
                outside.add((nr, nc)); q.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r, c) not in outside:
                out[r][c] = 8

    # The final 5 at the open end has a single 5-neighbor: mark it 7.
    pixels = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5}
    ends = []
    for r, c in pixels:
        degree = sum((r + dr, c + dc) in pixels for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
        if degree == 1:
            ends.append((r, c))
    if ends:
        # This drawing's designated terminal is the lowest endpoint.
        r, c = max(ends)
        out[r][c] = 7
    return out

if __name__ == '__main__':
    demo_in = [[5,0,0,5,0],[5,0,0,5,0],[5,0,5,5,5],[5,5,5,0,0],[0,0,5,0,0],[0,0,5,5,5],[0,0,0,5,0],[5,5,5,5,0],[0,5,0,0,0],[0,5,0,0,0],[0,5,5,5,0],[0,0,0,5,0],[0,5,5,5,5],[5,5,0,0,0],[0,5,0,0,0]]
    expected = [[5,0,0,5,0],[5,0,0,5,0],[5,0,5,5,5],[5,5,5,0,0],[0,0,5,0,0],[0,0,5,5,5],[0,0,0,5,8],[5,5,5,5,8],[0,5,8,8,8],[0,5,8,8,8],[0,5,5,5,8],[0,0,0,5,8],[0,5,5,5,5],[5,5,0,0,0],[7,5,0,0,0]]
    assert transform(demo_in) == expected
    test = [[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
    print(transform(test))
    print('demo verified')

if __name__ == '__main__':
